1	package main
2	
3	import (
4		"crypto/sha256"
5		"encoding/csv"
6		"encoding/hex"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"strconv"
12		"strings"
13		"time"
14	)
15	
16	// 用量导入文件（CSV，UTF-8，首行为固定表头，之后每行一条用量）：
17	//
18	//	usage_id,customer_id,time,quantity
19	//	u-001,cust-1,2026-09-15T10:00:00Z,100
20	//
21	//	usage_id   全局唯一用量标识，非空
22	//	customer_id 必须是已登记的客户标识
23	//	time       RFC3339 时间，如 2026-09-15T10:00:00Z 或 2026-09-15T18:00:00+08:00
24	//	quantity   正整数数量（有符号 64 位整数范围内）
25	const usageHeader = "usage_id,customer_id,time,quantity"
26	
27	// runCmd 解析并执行子命令。业务/用法错误通过 error 返回，由 main 统一
28	// 写入标准错误并以非零状态退出。
29	func runCmd(args []string, dataDir string) error {
30		switch args[0] {
31		case "customer":
32			if len(args) < 2 {
33				return usageError("缺少子命令，应为：customer add <标识> <名称> <单价分>")
34			}
35			switch args[1] {
36			case "add":
37				if len(args) != 5 {
38					return usageError("用法：customer add <标识> <名称> <单价分>")
39				}
40				return cmdCustomerAdd(dataDir, args[2], args[3], args[4])
41			default:
42				return usageError("未知 customer 子命令 %q；可用：add", args[1])
43			}
44	
45		case "usage":
46			if len(args) < 2 {
47				return usageError("缺少子命令，应为：usage import <文件>")
48			}
49			switch args[1] {
50			case "import":
51				if len(args) != 3 {
52					return usageError("用法：usage import <文件>（- 表示标准输入）")
53				}
54				return cmdUsageImport(dataDir, args[2])
55			default:
56				return usageError("未知 usage 子命令 %q；可用：import", args[1])
57			}
58	
59		case "bill":
60			if len(args) < 2 {
61				return usageError("缺少子命令，应为：bill settle|show|adjust|revoke ...")
62			}
63			switch args[1] {
64			case "settle":
65				if len(args) != 4 {
66					return usageError("用法：bill settle <客户标识> <YYYY-MM>")
67				}
68				return cmdBillSettle(dataDir, args[2], args[3])
69			case "show":
70				if len(args) != 4 {
71					return usageError("用法：bill show <客户标识> <YYYY-MM>")
72				}
73				return cmdBillShow(dataDir, args[2], args[3])
74			case "adjust":
75				if len(args) != 7 {
76					return usageError("用法：bill adjust <客户标识> <YYYY-MM> <调整标识> <金额分> <原因>")
77				}
78				return cmdBillAdjust(dataDir, args[2], args[3], args[4], args[5], args[6])
79			case "revoke":
80				if len(args) != 4 {
81					return usageError("用法：bill revoke <调整标识> <原因>")
82				}
83				return cmdBillRevoke(dataDir, args[2], args[3])
84			default:
85				return usageError("未知 bill 子命令 %q；可用：settle、show、adjust、revoke", args[1])
86			}
87	
88		default:
89			return usageError("未知命令 %q；可用：customer、usage、bill", args[0])
90		}
91	}
92	
93	type usageErrorf string
94	
95	func (e usageErrorf) Error() string { return string(e) }
96	
97	func usageError(format string, a ...any) error {
98		return usageErrorf(fmt.Sprintf(format, a...))
99	}
100	
101	func cmdCustomerAdd(dir, id, name, priceText string) error {
102		if strings.TrimSpace(id) == "" {
103			return fmt.Errorf("客户标识不能为空")
104		}
105		if strings.TrimSpace(name) == "" {
106			return fmt.Errorf("客户名称不能为空")
107		}
108		price, err := parsePrice(priceText)
109		if err != nil {
110			return err
111		}
112	
113		s, err := loadStore(dir)
114		if err != nil {
115			return err
116		}
117		if _, exists := s.Customers[id]; exists {
118			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
119		}
120		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
121		if err := s.save(); err != nil {
122			return err
123		}
124		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
125		return nil
126	}
127	
128	func parsePrice(text string) (int64, error) {
129		text = strings.TrimSpace(text)
130		price, err := strconv.ParseInt(text, 10, 64)
131		if err != nil {
132			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
133		}
134		if price < 0 {
135			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
136		}
137		return price, nil
138	}
139	
140	// parsedRow 是导入文件中一行解析后的候选用量。
141	type parsedRow struct {
142		line int // 文件中的行号（含表头），用于报错定位
143		rec  usageRecord
144		t    time.Time
145	}
146	
147	func cmdUsageImport(dir, file string) error {
148		var reader io.ReadCloser
149		var source string
150		if file == "-" {
151			reader = io.NopCloser(os.Stdin)
152			source = "标准输入"
153		} else {
154			f, err := os.Open(file)
155			if err != nil {
156				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
157			}
158			reader = f
159			source = file
160		}
161		defer reader.Close()
162	
163		rows, parseErrs := parseUsageFile(reader)
164	
165		s, err := loadStore(dir)
166		if err != nil {
167			return err
168		}
169	
170		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
171		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
172		var problems []string
173		problems = append(problems, parseErrs...)
174	
175		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
176		var ordered []*parsedRow
177		newCount, dupCount := 0, 0
178	
179		for _, r := range rows {
180			cust, ok := s.Customers[r.rec.CustomerID]
181			if !ok {
182				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
183				continue
184			}
185			// 金额可行性预检：数量×固定单价不得溢出（金额单位：分）。
186			if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
187				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
188				continue
189			}
190	
191			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
192			var existing *usageRecord
193			if inStore, ok := s.Usage[r.rec.ID]; ok {
194				existing = inStore
195			} else if inBatch, ok := accepted[r.rec.ID]; ok {
196				existing = &inBatch.rec
197			}
198	
199			if existing != nil {
200				if !sameUsage(existing, &r.rec, r.t) {
201					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
202						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
203					continue
204				}
205				dupCount++
206				continue
207			}
208	
209			// 全新标识：不得进入该客户已封账的 UTC 自然月。
210			month := r.t.UTC().Format("2006-01")
211			if s.sealed(r.rec.CustomerID, month) {
212				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
213					r.line, r.rec.CustomerID, month, r.rec.ID))
214				continue
215			}
216	
217			rr := r
218			accepted[r.rec.ID] = rr
219			ordered = append(ordered, rr)
220			newCount++
221		}
222	
223		if len(problems) > 0 {
224			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
225		}
226	
227		for _, r := range ordered {
228			rec := r.rec
229			s.Usage[rec.ID] = &rec
230		}
231		if err := s.save(); err != nil {
232			return err
233		}
234		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
235		return nil
236	}
237	
238	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
239	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
240		cr := csv.NewReader(r)
241		cr.FieldsPerRecord = 4
242		cr.TrimLeadingSpace = true
243	
244		header, err := cr.Read()
245		if err == io.EOF {
246			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
247		}
248		if err != nil {
249			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
250		}
251		for i := range header {
252			header[i] = strings.TrimSpace(header[i])
253		}
254		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
255			header[2] != "time" || header[3] != "quantity" {
256			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
257		}
258	
259		var rows []*parsedRow
260		var problems []string
261		line := 1
262		for {
263			rec, err := cr.Read()
264			if err == io.EOF {
265				break
266			}
267			line++
268			if err != nil {
269				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
270				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
271					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
272					break
273				}
274				continue
275			}
276			for i := range rec {
277				rec[i] = strings.TrimSpace(rec[i])
278			}
279	
280			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
281			if id == "" {
282				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
283				continue
284			}
285			if custID == "" {
286				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
287				continue
288			}
289			t, err := time.Parse(time.RFC3339, ts)
290			if err != nil {
291				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
292				continue
293			}
294			qty, err := strconv.ParseInt(qtyText, 10, 64)
295			if err != nil {
296				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
297				continue
298			}
299			if qty <= 0 {
300				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
301				continue
302			}
303	
304			rows = append(rows, &parsedRow{
305				line: line,
306				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
307				t:    t,
308			})
309		}
310		return rows, problems
311	}
312	
313	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
314	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
315	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
316		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
317			return false
318		}
319		et, err := time.Parse(time.RFC3339, existing.Time)
320		if err != nil {
321			return existing.Time == candidate.Time
322		}
323		return et.Equal(candidateT)
324	}
325	
326	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
327	func validMonth(m string) bool {
328		t, err := time.Parse("2006-01", m)
329		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
330			return false
331		}
332		return true
333	}
334	
335	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
336	func inMonth(rfc3339, month string) bool {
337		t, err := time.Parse(time.RFC3339, rfc3339)
338		if err != nil {
339			return false
340		}
341		return t.UTC().Format("2006-01") == month
342	}
343	
344	func cmdBillSettle(dir, customerID, month string) error {
345		if !validMonth(month) {
346			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
347		}
348		s, err := loadStore(dir)
349		if err != nil {
350			return err
351		}
352		cust, ok := s.Customers[customerID]
353		if !ok {
354			return fmt.Errorf("客户标识 %q 不存在", customerID)
355		}
356	
357		key := billKey(customerID, month)
358		if existing, ok := s.Bills[key]; ok {
359			// 幂等：同一客户同一月份重复结算，直接返回原账单，
360			// 不重新计费、不产生新账单或调整、不落盘。
361			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
362			printBill(existing, cust, adjustmentsFor(s, customerID, month))
363			return nil
364		}
365	
366		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
367		var inMonthRecs []*usageRecord
368		for _, u := range s.Usage {
369			if u.CustomerID == customerID && inMonth(u.Time, month) {
370				inMonthRecs = append(inMonthRecs, u)
371			}
372		}
373		if len(inMonthRecs) == 0 {
374			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
375		}
376		sortByInstant(inMonthRecs)
377	
378		lines := make([]billLine, 0, len(inMonthRecs))
379		var totalQty, totalFee int64
380		for _, u := range inMonthRecs {
381			lineFee, err := mul64(u.Quantity, cust.Price)
382			if err != nil {
383				return fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出，拒绝结算且不封账", u.ID, u.Quantity, cust.Price)
384			}
385			totalQty, err = add64(totalQty, u.Quantity)
386			if err != nil {
387				return fmt.Errorf("汇总数量溢出有符号 64 位整数范围，拒绝结算且不封账")
388			}
389			totalFee, err = add64(totalFee, lineFee)
390			if err != nil {
391				return fmt.Errorf("汇总金额溢出有符号 64 位整数范围，拒绝结算且不封账")
392			}
393			lines = append(lines, billLine{
394				UsageID:  u.ID,
395				Time:     u.Time,
396				Quantity: u.Quantity,
397				LineFee:  lineFee,
398			})
399		}
400	
401		b := &bill{
402			ID:         stableBillID(customerID, month),
403			CustomerID: customerID,
404			Month:      month,
405			TotalQty:   totalQty,
406			UnitPrice:  cust.Price,
407			TotalFee:   totalFee,
408			Lines:      lines,
409			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
410		}
411		s.Bills[key] = b
412	
413		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
414		if err := s.save(); err != nil {
415			delete(s.Bills, key)
416			return err
417		}
418		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
419		printBill(b, cust, nil)
420		return nil
421	}
422	
423	func cmdBillShow(dir, customerID, month string) error {
424		if !validMonth(month) {
425			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
426		}
427		s, err := loadStore(dir)
428		if err != nil {
429			return err
430		}
431		cust, ok := s.Customers[customerID]
432		if !ok {
433			return fmt.Errorf("客户标识 %q 不存在", customerID)
434		}
435		b, ok := s.Bills[billKey(customerID, month)]
436		if !ok {
437			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
438		}
439		printBill(b, cust, adjustmentsFor(s, customerID, month))
440		return nil
441	}
442	
443	func sortByInstant(us []*usageRecord) {
444		// 入参时间均已在载入/导入时校验为 RFC3339。
445		sort.Slice(us, func(i, j int) bool {
446			ti, _ := time.Parse(time.RFC3339, us[i].Time)
447			tj, _ := time.Parse(time.RFC3339, us[j].Time)
448			ui, uj := ti.UTC(), tj.UTC()
449			if !ui.Equal(uj) {
450				return ui.Before(uj)
451			}
452			return us[i].ID < us[j].ID
453		})
454	}
455	
456	// stableBillID 由（客户标识，月份）确定性派生：跨进程稳定，且客户/月份间唯一。
457	func stableBillID(customerID, month string) string {
458		sum := sha256.Sum256([]byte(customerID + "\x00" + month))
459		return "BILL-" + hex.EncodeToString(sum[:])[:16]
460	}
461	
462	func printBill(b *bill, cust *customer, adjs []*adjustment) {
463		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
464		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
465		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
466		fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
467		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
468		fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
469		// 数据在载入时已校验一致，此处计算不会出错。
470		net, payable, _ := billTotals(b, adjs)
471		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
472		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
473		fmt.Fprintln(stdout, "明细：")
474		for i, ln := range b.Lines {
475			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
476				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
477		}
478		if len(adjs) == 0 {
479			fmt.Fprintln(stdout, "调整与撤销历史：无")
480			return
481		}
482		fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
483		for i, ev := range historyEvents(adjs) {
484			fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
485		}
486	}
487	
488	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
489	func historyEvents(adjs []*adjustment) []string {
490		type event struct {
491			seq  int64
492			text string
493		}
494		var events []event
495		for _, a := range adjs {
496			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
497				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
498			if a.Revoked {
499				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
500					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
501			}
502		}
503		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
504		out := make([]string, len(events))
505		for i, ev := range events {
506			out[i] = ev.text
507		}
508		return out
509	}
510	
511	func adjustKind(amount int64) string {
512		if amount > 0 {
513			return "补收"
514		}
515		return "减免"
516	}
517	
518	func adjustStatus(a *adjustment) string {
519		if a.Revoked {
520			return "已撤销"
521		}
522		return "生效中"
523	}
524	
525	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
526	func parseAmount(text string) (int64, error) {
527		text = strings.TrimSpace(text)
528		amount, err := strconv.ParseInt(text, 10, 64)
529		if err != nil {
530			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
531		}
532		if amount == 0 {
533			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
534		}
535		return amount, nil
536	}
537	
538	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
539		if !validMonth(month) {
540			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
541		}
542		if strings.TrimSpace(adjID) == "" {
543			return fmt.Errorf("调整标识不能为空")
544		}
545		amount, err := parseAmount(amountText)
546		if err != nil {
547			return err
548		}
549		if strings.TrimSpace(reason) == "" {
550			return fmt.Errorf("调整原因不能为空")
551		}
552	
553		s, err := loadStore(dir)
554		if err != nil {
555			return err
556		}
557		if _, ok := s.Customers[customerID]; !ok {
558			return fmt.Errorf("客户标识 %q 不存在", customerID)
559		}
560		b, ok := s.Bills[billKey(customerID, month)]
561		if !ok {
562			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
563		}
564	
565		if existing, ok := s.Adjustments[adjID]; ok {
566			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
567			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
568			if existing.CustomerID == customerID && existing.Month == month &&
569				existing.Amount == amount && existing.Reason == reason {
570				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
571				printAdjustment(existing, s)
572				return nil
573			}
574			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
575				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
576		}
577	
578		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
579		// [0, 有符号 64 位最大值] 内，否则拒绝且不占用该调整标识。
580		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
581		if err != nil {
582			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
583		}
584		newPayable, err := addSigned64(payable, amount)
585		if err != nil {
586			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
587		}
588		if newPayable < 0 {
589			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
590		}
591	
592		a := &adjustment{
593			ID:         adjID,
594			CustomerID: customerID,
595			Month:      month,
596			Amount:     amount,
597			Reason:     reason,
598			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
599		}
600		s.NextSeq++
601		a.Seq = s.NextSeq
602		s.Adjustments[adjID] = a
603	
604		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
605		// 该调整标识不被占用。
606		if err := s.save(); err != nil {
607			delete(s.Adjustments, adjID)
608			s.NextSeq--
609			return err
610		}
611		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
612			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
613		printAdjustment(a, s)
614		return nil
615	}
616	
617	func cmdBillRevoke(dir, adjID, reason string) error {
618		if strings.TrimSpace(adjID) == "" {
619			return fmt.Errorf("调整标识不能为空")
620		}
621		if strings.TrimSpace(reason) == "" {
622			return fmt.Errorf("撤销原因不能为空")
623		}
624	
625		s, err := loadStore(dir)
626		if err != nil {
627			return err
628		}
629		a, ok := s.Adjustments[adjID]
630		if !ok {
631			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
632		}
633	
634		if a.Revoked {
635			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
636			// 改用其他原因则拒绝。
637			if a.RevokeReason == reason {
638				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
639				printAdjustment(a, s)
640				return nil
641			}
642			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
643		}
644	
645		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界则拒绝，
646		// 该调整仍保持有效，可在其他合法调整改变余额后重试。
647		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
648		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
649		if err != nil {
650			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
651		}
652		neg, err := neg64(a.Amount)
653		if err != nil {
654			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
655		}
656		newPayable, err := addSigned64(payable, neg)
657		if err != nil {
658			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
659				payable, a.Amount)
660		}
661		if newPayable < 0 {
662			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
663				newPayable, payable, a.Amount)
664		}
665	
666		a.Revoked = true
667		a.RevokeReason = reason
668		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
669		s.NextSeq++
670		a.RevokeSeq = s.NextSeq
671	
672		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
673		if err := s.save(); err != nil {
674			a.Revoked = false
675			a.RevokeReason = ""
676			a.RevokedAt = ""
677			a.RevokeSeq = 0
678			s.NextSeq--
679			return err
680		}
681		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
682			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
683		printAdjustment(a, s)
684		return nil
685	}
686	
687	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
688	func printAdjustment(a *adjustment, s *state) {
689		b := s.Bills[billKey(a.CustomerID, a.Month)]
690		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
691		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
692		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
693		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
694		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
695		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
696		if a.Revoked {
697			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
698		} else {
699			fmt.Fprintf(stdout, "当前状态：生效中\n")
700		}
701		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
702	}
