32		ID         string `json:"id"`
33		CustomerID string `json:"customer_id"`
34		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
35		Quantity   int64  `json:"quantity"`
36	}
37	
38	type billLine struct {
39		UsageID  string `json:"usage_id"`
40		Time     string `json:"time"`
41		Quantity int64  `json:"quantity"`
42		LineFee  int64  `json:"line_fee_fen"`
43	}
44	
45	type bill struct {
46		ID         string     `json:"id"`
47		CustomerID string     `json:"customer_id"`
48		Month      string     `json:"month"` // YYYY-MM（UTC）
49		TotalQty   int64      `json:"total_quantity"`
50		UnitPrice  int64      `json:"unit_price_fen"`
51		TotalFee   int64      `json:"total_fee_fen"`
52		Lines      []billLine `json:"lines"`
53		CreatedAt  string     `json:"created_at"`
54	}
55	
56	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
57	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
58	type adjustment struct {
59		ID           string `json:"id"`
60		CustomerID   string `json:"customer_id"`
61		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
62		Amount       int64  `json:"amount_fen"`
63		Reason       string `json:"reason"`
64		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
65		CreatedAt    string `json:"created_at"`
66		Revoked      bool   `json:"revoked"`
67		RevokeReason string `json:"revoke_reason,omitempty"`
68		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
69		RevokedAt    string `json:"revoked_at,omitempty"`
70	}
71	
72	type state struct {
73		Version     int                     `json:"version"`
74		Customers   map[string]*customer    `json:"customers"`
75		Usage       map[string]*usageRecord `json:"usage"`       // 全局唯一用量标识 -> 记录
76		Bills       map[string]*bill        `json:"bills"`       // 客户 + "|" + 月份 -> 账单
77		Adjustments map[string]*adjustment  `json:"adjustments"` // 全局唯一调整标识 -> 记录
78		NextSeq     int64                   `json:"next_seq"`    // 已分配的最大操作序号（调整/撤销共用）
79		path        string                  `json:"-"`
80	}
81	
82	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
83	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
84	func loadStore(dir string) (*state, error) {
85		p := filepath.Join(dir, "state.json")
86		data, err := os.ReadFile(p)
87		if err != nil {
88			if errors.Is(err, os.ErrNotExist) {
89				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
90					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
91				}
92				return newState(p), nil
93			}
94			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
95		}
96	
97		var s state
98		dec := json.NewDecoder(bytes.NewReader(data))
99		if err := dec.Decode(&s); err != nil {
100			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
101		}
102		// 拒绝尾部多余内容，避免静默吞掉异常数据。
103		if dec.More() {
104			return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
105		}
106		if err := s.validate(); err != nil {
107			return nil, fmt.Errorf("数据文件已损坏: %w", err)
108		}
109		// 旧版本数据文件没有 adjustments/next_seq 字段：视为零调整。
110		if s.Adjustments == nil {
111			s.Adjustments = map[string]*adjustment{}
112		}
113		s.path = p
114		return &s, nil
115	}
116	
117	func newState(p string) *state {
118		return &state{
119			Version:     stateVersion,
120			Customers:   map[string]*customer{},
121			Usage:       map[string]*usageRecord{},
122			Bills:       map[string]*bill{},
123			Adjustments: map[string]*adjustment{},
124			path:        p,
125		}
126	}
127	
128	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
129	func (s *state) validate() error {
130		if s.Version != stateVersion {
131			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
132		}
133		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
134			return errors.New("缺少必要的数据节")
135		}
136		for id, c := range s.Customers {
137			if c == nil {
138				return fmt.Errorf("客户 %q 的数据为空", id)
139			}
140			if c.ID != id {
141				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
142			}
143			if c.ID == "" || c.Name == "" {
144				return fmt.Errorf("客户 %q 的标识或名称为空", id)
145			}
146			if c.Price < 0 {
147				return fmt.Errorf("客户 %q 单价为负", id)
148			}
149		}
150		for id, u := range s.Usage {
151			if u == nil {
152				return fmt.Errorf("用量 %q 的数据为空", id)
153			}
154			if u.ID != id {
155				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
156			}
157			if u.ID == "" {
158				return errors.New("存在空的用量标识")
159			}
160			if _, ok := s.Customers[u.CustomerID]; !ok {
161				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
162			}
163			if u.Quantity <= 0 {
164				return fmt.Errorf("用量 %q 的数量非正", u.ID)
165			}
166			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
167				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
168			}
169		}
170		for key, b := range s.Bills {
171			if b == nil {
172				return fmt.Errorf("账单 %q 的数据为空", key)
173			}
174			if billKey(b.CustomerID, b.Month) != key {
175				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
176			}
177			if _, ok := s.Customers[b.CustomerID]; !ok {
178				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
179			}
180			if !validMonth(b.Month) {
181				return fmt.Errorf("账单 %q 的月份无效", key)
182			}
183			if len(b.Lines) == 0 {
184				return fmt.Errorf("账单 %q 没有明细", key)
185			}
186			var qty, fee int64
187			for _, ln := range b.Lines {
188				u, ok := s.Usage[ln.UsageID]
189				if !ok {
190					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
191				}
192				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
193					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
194				}
195				if !inMonth(u.Time, b.Month) {
196					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
197				}
198				var err error
199				qty, err = add64(qty, ln.Quantity)
200				if err != nil {
201					return fmt.Errorf("账单 %q 汇总数量溢出", key)
202				}
203				fee, err = add64(fee, ln.LineFee)
204				if err != nil {
205					return fmt.Errorf("账单 %q 汇总金额溢出", key)
206				}
207			}
208			if qty != b.TotalQty {
209				return fmt.Errorf("账单 %q 总数量与明细不符", key)
210			}
211			if fee != b.TotalFee {
212				return fmt.Errorf("账单 %q 总金额与明细不符", key)
213			}
214			c := s.Customers[b.CustomerID]
215			for _, ln := range b.Lines {
216				lf, err := mul64(ln.Quantity, c.Price)
217				if err != nil {
218					return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
219				}
220				if lf != ln.LineFee {
221					return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
222				}
223			}
224			if b.UnitPrice != c.Price {
225				return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
226			}
227			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
228			// 而已入账记录理应全部在明细中）。
229			for _, u := range s.Usage {
230				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
231					found := false
232					for _, ln := range b.Lines {
233						if ln.UsageID == u.ID {
234							found = true
235							break
236						}
237					}
238					if !found {
239						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
240					}
241				}
242			}
243		}
244	
245		// 调整记录：标识、内容、引用与序号都必须自洽。
246		if s.NextSeq < 0 {
247			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
248		}
249		seenSeq := make(map[int64]string)
250		seenRevokeSeq := make(map[int64]string)
251		for id, a := range s.Adjustments {
252			if a == nil {
253				return fmt.Errorf("调整 %q 的数据为空", id)
254			}
255			if a.ID != id {
256				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
257			}
258			if a.ID == "" {
259				return errors.New("存在空的调整标识")
260			}
261			if a.Amount == 0 {
262				return fmt.Errorf("调整 %q 的金额为零", id)
263			}
264			if strings.TrimSpace(a.Reason) == "" {
265				return fmt.Errorf("调整 %q 的原因为空", id)
266			}
267			if !validMonth(a.Month) {
268				return fmt.Errorf("调整 %q 的月份无效", id)
269			}
270			if _, ok := s.Customers[a.CustomerID]; !ok {
271				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
272			}
273			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
274				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
275			}
276			if a.Seq < 1 || a.Seq > s.NextSeq {
277				return fmt.Errorf("调整 %q 的操作序号越界", id)
278			}
279			if prev, dup := seenSeq[a.Seq]; dup {
280				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
281			}
282			seenSeq[a.Seq] = id
283			if a.Revoked {
284				if strings.TrimSpace(a.RevokeReason) == "" {
285					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
286				}
287				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
288					return fmt.Errorf("调整 %q 的撤销序号越界", id)
289				}
290				if prev, dup := seenRevokeSeq[a.RevokeSeq]; dup {
291					return fmt.Errorf("调整 %q 与 %q 的撤销序号重复", id, prev)
292				}
293				seenRevokeSeq[a.RevokeSeq] = id
294			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
295				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
296			}
297		}
298		// 每张账单的当前应付（原总金额 + 全部未撤销调整金额）必须介于
299		// 0 与有符号 64 位最大值之间；越界说明金额与记录不一致。
300		for key, b := range s.Bills {
301			if _, _, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month)); err != nil {
302				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
303			}
304		}
305		return nil
306	}
307	
308	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
309	// 只有完整保存成功后调用方才会向用户报告成功。
310	func (s *state) save() error {
311		if err := s.validate(); err != nil {
312			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
313		}
314		data, err := json.MarshalIndent(s, "", "  ")
315		if err != nil {
316			return fmt.Errorf("序列化数据失败: %w", err)
317		}
318		data = append(data, '\n')
319	
320		tmp := s.path + ".tmp"
321		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
322		if err != nil {
323			return fmt.Errorf("写入临时数据文件失败: %w", err)
324		}
325		if _, err := f.Write(data); err != nil {
326			f.Close()
327			os.Remove(tmp)
328			return fmt.Errorf("写入临时数据文件失败: %w", err)
329		}
330		if err := f.Sync(); err != nil {
331			f.Close()
332			os.Remove(tmp)
333			return fmt.Errorf("同步数据文件失败: %w", err)
334		}
335		if err := f.Close(); err != nil {
336			os.Remove(tmp)
337			return fmt.Errorf("关闭数据文件失败: %w", err)
338		}
339		if err := os.Rename(tmp, s.path); err != nil {
340			os.Remove(tmp)
341			return fmt.Errorf("替换数据文件失败: %w", err)
342		}
343		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
344			dir.Sync()
345			dir.Close()
346		}
347		return nil
348	}
349	
350	func billKey(customerID, month string) string {
351		return customerID + "|" + month
352	}
353	
354	// sealed 报告某客户的指定月份是否已封账。
355	func (s *state) sealed(customerID, month string) bool {
356		_, ok := s.Bills[billKey(customerID, month)]
357		return ok
358	}
359	
360	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
361	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
362		var list []*adjustment
363		for _, a := range s.Adjustments {
364			if a.CustomerID == customerID && a.Month == month {
365				list = append(list, a)
366			}
367		}
368		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
369		return list
370	}
371	
372	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
373	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
374	
375	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
376	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
377	// [0, 有符号 64 位最大值] 内，全程整数运算。
378	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
379		var amounts []int64
380		for _, a := range adjs {
381			if !a.Revoked {
382				amounts = append(amounts, a.Amount)
383			}
384		}
385		net, err = sumSigned64(amounts...)
386		if err != nil {
387			return 0, 0, err
388		}
389		payable, err = addSigned64(b.TotalFee, net)
390		if err != nil {
391			return 0, 0, err
392		}
393		if payable < 0 {
394			return 0, 0, errPayableOutOfRange
395		}
396		return net, payable, nil
397	}
398

