package main

import (
	"errors"
	"math"
	"math/bits"
	"strconv"
)

// 金额、单价、数量均使用有符号 64 位整数（金额单位：人民币分），
// 全程整数运算，不经过浮点数。

var errOverflow = errors.New("数量或金额运算超出有符号 64 位整数范围")

// mul64 返回 a*b，溢出时返回错误。a、b 均非负。
func mul64(a, b int64) (int64, error) {
	if a < 0 || b < 0 {
		return 0, errOverflow
	}
	if a == 0 || b == 0 {
		return 0, nil
	}
	if a > math.MaxInt64/b {
		return 0, errOverflow
	}
	return a * b, nil
}

// add64 返回 a+b，溢出时返回错误。a、b 均非负。
func add64(a, b int64) (int64, error) {
	if a < 0 || b < 0 || a > math.MaxInt64-b {
		return 0, errOverflow
	}
	return a + b, nil
}

// addSigned64 返回 a+b（允许负数），溢出时返回错误。
func addSigned64(a, b int64) (int64, error) {
	if (b > 0 && a > math.MaxInt64-b) || (b < 0 && a < math.MinInt64-b) {
		return 0, errOverflow
	}
	return a + b, nil
}

// neg64 返回 -a；a 为 math.MinInt64 时无法表示，返回错误。
func neg64(a int64) (int64, error) {
	if a == math.MinInt64 {
		return 0, errOverflow
	}
	return -a, nil
}

// sumSigned64 精确求和一组有符号 64 位整数（内部按 128 位累加，
// 与求和顺序无关），最终结果超出有符号 64 位范围时返回错误。
func sumSigned64(vals ...int64) (int64, error) {
	var hi, lo uint64
	for _, v := range vals {
		var carry uint64
		lo, carry = bits.Add64(lo, uint64(v), 0)
		// 符号扩展 v 的高位后连同进位一起累加。
		sign := uint64(0)
		if v < 0 {
			sign = math.MaxUint64
		}
		hi, _ = bits.Add64(hi, sign, carry)
	}
	switch {
	case hi == 0 && lo <= math.MaxInt64:
		return int64(lo), nil
	case hi == math.MaxUint64 && lo >= 1<<63:
		return int64(lo), nil
	default:
		return 0, errOverflow
	}
}

// moneyFen 将“分”渲染为人民币金额，如 1234 -> "12.34 元"，5 -> "0.05 元"。
func moneyFen(fen int64) string {
	neg := fen < 0
	// 用无符号数取绝对值，避免 math.MinInt64 取负溢出。
	u := uint64(fen)
	if neg {
		u = uint64(-(fen + 1)) + 1
	}
	s := strconv.FormatUint(u, 10)
	if len(s) < 3 {
		s = "00" + s
		s = s[len(s)-3:]
	}
	whole, frac := s[:len(s)-2], s[len(s)-2:]
	out := whole + "." + frac + " 元"
	if neg {
		out = "-" + out
	}
	return out
}

package main

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// 每个用例使用独立临时数据目录，每次调用 run 都重新从磁盘载入，
// 天然模拟“跨进程”持久化。

type harness struct {
	t   *testing.T
	dir string
	buf bytes.Buffer
}

func newHarness(t *testing.T) *harness {
	t.Helper()
	h := &harness{t: t, dir: t.TempDir()}
	prev := stdout
	stdout = &h.buf
	t.Cleanup(func() { stdout = prev })
	return h
}

func (h *harness) run(args ...string) (string, error) {
	h.buf.Reset()
	full := append([]string{"--data-dir", h.dir}, args...)
	err := run(full)
	return h.buf.String(), err
}

func (h *harness) mustRun(args ...string) string {
	h.t.Helper()
	out, err := h.run(args...)
	if err != nil {
		h.t.Fatalf("run %v 意外失败: %v", args, err)
	}
	return out
}

func (h *harness) runExpectErr(args ...string) string {
	h.t.Helper()
	out, err := h.run(args...)
	if err == nil {
		h.t.Fatalf("run %v 应失败却成功，输出:\n%s", args, out)
	}
	return err.Error()
}

func (h *harness) writeFile(name, content string) string {
	h.t.Helper()
	p := filepath.Join(h.dir, name)
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		h.t.Fatal(err)
	}
	return p
}

func (h *harness) statePath() string { return filepath.Join(h.dir, "state.json") }

const csvHeader = "usage_id,customer_id,time,quantity\n"

func TestHelpAndNoArgs(t *testing.T) {
	h := newHarness(t)
	for _, args := range [][]string{nil, {"--help"}, {"-h"}} {
		out, err := h.run(args...)
		if err != nil {
			t.Fatalf("args=%v 出错: %v", args, err)
		}
		if !strings.Contains(out, "planbill") || !strings.Contains(out, "customer add") {
			t.Fatalf("args=%v 帮助内容异常:\n%s", args, out)
		}
	}
}

func TestInvalidCommandsExitNonzeroWithUsageError(t *testing.T) {
	h := newHarness(t)
	cases := [][]string{
		{"bogus"},
		{"customer"},
		{"customer", "delete", "x"},
		{"usage"},
		{"usage", "export"},
		{"bill"},
		{"bill", "frobnicate", "c", "2026-09"},
		{"customer", "add", "only-two"},
		{"--help", "customer"},
	}
	for _, args := range cases {
		_, err := h.run(args...)
		var ue usageErrorf
		if !errors.As(err, &ue) {
			t.Fatalf("args=%v 应为用法错误(2)，得到 %v", args, err)
		}
	}
}

func TestCustomerRegistrationValidation(t *testing.T) {
	h := newHarness(t)

	out := h.mustRun("customer", "add", "c1", "甲方", "150")
	if !strings.Contains(out, "已登记客户") {
		t.Fatal(out)
	}

	// 重复标识拒绝。
	h.runExpectErr("customer", "add", "c1", "另一个名称", "200")
	// 空标识 / 纯空白标识、空名称拒绝。
	h.runExpectErr("customer", "add", "", "名称", "100")
	h.runExpectErr("customer", "add", "   ", "名称", "100")
	h.runExpectErr("customer", "add", "c2", "", "100")
	h.runExpectErr("customer", "add", "c2", "   ", "100")
	// 单价必须是非负整数分。
	h.runExpectErr("customer", "add", "c2", "名称", "-1")
	h.runExpectErr("customer", "add", "c2", "名称", "1.5")
	h.runExpectErr("customer", "add", "c2", "名称", "abc")
	h.runExpectErr("customer", "add", "c2", "名称", "99999999999999999999999")

	// 零单价合法；且重复登记被拒后库状态不变（c2 仍可首次创建）。
	h.mustRun("customer", "add", "c2", "乙方", "0")
	out = h.mustRun("customer", "add", "c3", "丙", "10")
	_ = out
}

func TestImportHappyPathAndDuplicateReplay(t *testing.T) {
	h := newHarness(t)
	h.mustRun("customer", "add", "c1", "甲方", "100")

	f := h.writeFile("u1.csv", csvHeader+
