// paymentEvents 把收款与撤销收款展开为按操作序号排序的可读历史条目。
func paymentEvents(pays []*payment) []string {
	type event struct {
		seq  int64
		text string
	}
	var events []event
	for _, p := range pays {
		events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：%d 分（%s），备注：%s，当前状态：%s",
			p.ID, p.Amount, moneyFen(p.Amount), p.Note, paymentStatus(p))})
		if p.Revoked {
