// parsePaymentAmount 解析收款金额：正整数分（有符号 64 位整数范围内）。
func parsePaymentAmount(text string) (int64, error) {
	text = strings.TrimSpace(text)
	amount, err := strconv.ParseInt(text, 10, 64)
