		return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
	}
	if amount <= 0 {
		return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
	}
